={{ {
  model: "llama-3.3-70b-versatile",
  messages: [{
    role: "user",
    content: (() => {
      const report = $json.trendAnalysis ? JSON.parse($json.trendAnalysis) : $json;
      const keywords = $("Keyword Generator").first()?.json?.keywords || [];
      const niche        = report.niche || "";
      const designStyle  = report.design_style || "bold two-word phrases, emoji combos, ironic one-liners";
      const redditCtx    = report.reddit_context || "";
      const topDirs      = (report.topDesignDirections    || []).slice(0, 5).join(", ");
      const emerging     = (report.emergingTrends         || []).slice(0, 5).join(", ");
      const unsaturated  = (report.underservedOpportunities || []).slice(0, 3).join(", ");
      const audiences    = (report.audienceSegments       || []).slice(0, 5).join(", ");
      const colors       = (report.recurringColors        || []).slice(0, 5).join(", ");
      const typo         = (report.typographyStyles       || []).slice(0, 3).join(", ");
      const icons        = (report.illustrations          || []).slice(0, 8).join(", ");
      return "You are a creative director for a POD t-shirt brand.\n\n"
           + "NICHE: " + niche + "\n\n"
           + "BRAND KEYWORDS (use these as inspiration for phrases):\n"
           + keywords.join(", ") + "\n\n"
           + "DESIGN STYLE REQUIREMENTS (strictly follow these):\n"
           + designStyle + "\n\n"
           + "REDDIT COMMUNITY CONTEXT (use this language/culture):\n"
           + redditCtx + "\n\n"
           + "TREND DATA:\n"
           + "Top Directions: " + topDirs + "\n"
           + "Emerging: " + emerging + "\n"
           + "Underserved: " + unsaturated + "\n"
           + "Audiences: " + audiences + "\n"
           + "Colors: " + colors + "\n"
           + "Typography: " + typo + "\n"
           + "Icons: " + icons + "\n\n"
           + "Generate EXACTLY 10 original t-shirt design concepts. "
           + "Each phrase must match the design style. "
           + "Incorporate the brand keywords where they fit naturally.\n\n"
           + "Return ONLY a JSON array of exactly 10 objects, no markdown:\n"
           + "[{\"id\":1,\"title\":\"\",\"concept\":\"\",\"targetAudience\":\"\",\"sellingAngle\":\"\",\"tone\":\"\",\"phrase\":\"\",\"imagePrompt\":\"\",\"colors\":[],\"typography\":\"\",\"icons\":[],\"source\":\"\"}]";
    })()
  }],
  temperature: 0.85,
  max_tokens: 4000
} }}

parameters.jsCode:
const raw = $input.first().json?.choices?.[0]?.message?.content || '[]';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\[[\s\S]*\]/);
let concepts = [];
try { concepts = JSON.parse(match?.[0] || '[]'); } catch (_) {}

const input = $('Execute Workflow Trigger').first().json;
const report = input.trendAnalysis ? JSON.parse(input.trendAnalysis) : input;
const niche = report.niche || '';

// Score each concept — prefer opportunity/underserved, then twitter, then seasonal
const scores = { opportunity: 3, underserved: 3, twitter: 2, seasonal: 1, evergreen: 1 };
const scored = concepts.map(c => ({ ...c, _score: scores[c.source] || 1 }));
const best = scored.sort((a, b) => b._score - a._score)[0] || concepts[0];
delete best?._score;

// Return single best concept (not an array) — one image per niche
return [{ json: { niche, concept: best, concepts } }];
